/* @lc app=leetcode id=1631 lang=kotlin */ class Solution { fun minimumEffortPath(heights: Array<IntArray>): Int = Array(heights.size) { IntArray(heights[0].size) { Int.MAX_VALUE } }.also { it[0][0] = 0 }.let { d -> java.util.PriorityQueue<IntArray>(compareBy<IntArray> { it[0] }).also { it.add(intArrayOf(0, 0, 0)) }.let { pq -> generateSequence { pq.poll() }.filter { c -> c[0] == d[c[1]][c[2]] }.forEach { c -> listOf(1 to 0, -1 to 0, 0 to 1, 0 to -1).map { (dr, dc) -> c[1] + dr to c[2] + dc }.filter { (r, cc) -> r in heights.indices && cc in heights[0].indices }.map { (r, cc) -> intArrayOf(maxOf(c[0], Math.abs(heights[r][cc] - heights[c[1]][c[2]])), r, cc) }.filter { it[0] < d[it[1]][it[2]] }.forEach { x -> pq.add(x).also { d[x[1]][x[2]] = x[0] } } }.let { d[heights.size - 1][heights[0].size - 1] } } } }